from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = dict(jumps)

    # Resolve every jump chain.
    destination = {}
    for cell in range(n + 1):
        path = []
        current = cell
        while current not in destination and current in jump:
            path.append(current)
            current = jump[current]

        end = destination.get(current, current)
        destination[current] = end
        for current in path:
            destination[current] = end

    # Build the reachable transition graph, counting die outcomes.
    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    reachable = {0}
    pending = [0]

    while pending:
        cell = pending.pop()
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            target = destination[landing]
            counts[target] = counts.get(target, 0) + 1

        transitions[cell] = counts
        for target in counts:
            reverse[target].append(cell)
            if target not in reachable:
                reachable.add(target)
                pending.append(target)

    # A finite chain terminates almost surely exactly when every reachable
    # state has a path to the terminal state.
    can_finish = {n}
    pending = [n]
    while pending:
        cell = pending.pop()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                pending.append(previous)

    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    # Integer equations: m * E[cell] - sum(count * E[target]) = m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    # Fraction-free Bareiss elimination. This transient Markov-chain
    # matrix has nonzero leading principal minors, so no pivoting is needed.
    previous_pivot = 1
    for k in range(size - 1):
        pivot_row = matrix[k]
        pivot = pivot_row[k]
        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0
        previous_pivot = pivot

    expectations = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectations[j]
        expectations[i] = value / matrix[i][i]

    answer = expectations[index[0]]
    return [answer.numerator, answer.denominator]
